const grid=document.getElementById("productGrid");
products.forEach(p=>{
  const card=document.createElement("article");
  card.className="product-card";
  card.innerHTML=`<div class="product-image"><img src="${p.img}" alt="${p.title}"></div>
  <div class="product-info"><h3>${p.title}</h3><p>${p.sub}</p><button class="arrow" aria-label="View ${p.title}">→</button></div>`;
  card.querySelector(".arrow").addEventListener("click",()=>openProduct(p));
  grid.appendChild(card);
});

document.getElementById("aboutImage").src=IMG.about_img;

const modal=document.getElementById("productModal");
const body=document.getElementById("modalBody");
function openProduct(p){
  body.innerHTML=`<h2>${p.title}</h2><p class="modal-sub">${p.sub}</p><div class="gallery">${
    p.gallery.map(g=>`<div class="gallery-item"><img class="${g[2]||""}" src="${g[1]}" alt="${g[0]}"><b>${g[0]}</b></div>`).join("")
  }</div>`;
  modal.classList.add("open");
  modal.setAttribute("aria-hidden","false");
}
function closeProduct(){modal.classList.remove("open");modal.setAttribute("aria-hidden","true")}
document.querySelector(".close").addEventListener("click",closeProduct);
modal.addEventListener("click",e=>{if(e.target===modal)closeProduct()});
document.addEventListener("keydown",e=>{if(e.key==="Escape")closeProduct()});

document.querySelector(".menu").addEventListener("click",()=>{
  const nav=document.querySelector(".navlinks");
  nav.style.display=nav.style.display==="flex"?"none":"flex";
  if(nav.style.display==="flex"){nav.style.position="absolute";nav.style.top="64px";nav.style.right="0";nav.style.background="#fff";nav.style.padding="14px";nav.style.flexDirection="column";nav.style.alignItems="stretch";nav.style.boxShadow="0 8px 20px #0002"}
});
